module tb_TopModule;
    logic         clk;
    logic         load;
    logic   [1:0] ena;
    logic [99:0]  data;
    logic [99:0]  q;

    TopModule dut (
        .clk(clk),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        load = 0;
        ena = 2'b00;
        data = 100'h0;
        @(posedge clk);

        // Test load
        data = 100'h123456789ABCDEF0123456789;
        load = 1;
        @(posedge clk);
        load = 0;
        if (q !== 100'h123456789ABCDEF0123456789) begin
            $display("SELFFAIL: load failed. q = %h", q);
            $finish;
        end

        // Test rotate right (2'b01)
        // 100'h123456789ABCDEF0123456789
        // LSB is bit 0. Let's test with a simpler pattern.
        data = 100'h3; // bit 1 and bit 0 are 1, rest 0
        load = 1;
        @(posedge clk);
        load = 0;

        ena = 2'b01; // rotate right
        @(posedge clk);
        // q should be shifted right by 1 with wrap around.
        // 3 -> binary ...0011 -> right rotate 1 -> ...0001 with MSB getting old LSB (1) -> bit 99 is 1, bit 0 is 1? Wait.
        // 3 is binary 0...011. bits 1 and 0 are 1.
        // {q[0], q[99:1]} -> q[0] was 1, so MSB becomes 1. q[99:1] shifted right. Bit 1 becomes bit 0, bit 0 becomes bit 99.
        $display("After rotate right: q = %h", q);

        // Test rotate left (2'b10)
        data = 100'h1; // bit 0 is 1
        load = 1;
        @(posedge clk);
        load = 0;

        ena = 2'b10; // rotate left
        @(posedge clk);
        // q should be {q[98:0], q[99]} -> bit 0 was 1, rotated left -> bit 1 becomes 1.
        $display("After rotate left: q = %h", q);
        if (q !== 100'h2) begin
            $display("SELFFAIL: rotate left failed. q = %h", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

